// gww-c2-v2 — generated by tools/generate.py v2 from DNA 'gww' (seed 22, energy 0.9)
// 124 BPM · F#m (11A) · 184 bars ≈ 5.94 min · kit: own
// novelty vs source loops (0 = copy, 1 = nothing in common): bass bar 0.625 / 2-bar 0.75 · hook bar 0.625
// DJ structure: intro 16 bars & outro 16 bars drums-led, 8-bar phrases, constant tempo.
setcpm(124/4)

// ---- live controls (sliders on strudel.cc, plain values elsewhere)
const LIVE = typeof sliderWithID !== 'undefined'
const ENERGY = LIVE ? slider(1.16, 0, 1.5) : 1.16   // hats / perc / shaker level
const BASS_ENV = LIVE ? slider(3, 0, 6) : 3   // bass body filter envelope depth
const CUT = 1050   // bass body cutoff (Hz) when the bass is open
const PUMP = "[0.28 0.68 1 0.94]*4"   // sidechain-style ducking per 16th (kick on the 1st 16th of each beat)
const ATT = "[.022 .004 .003 .004]*4"   // softer attack on the kick 16ths = duck

// ---- arrangement: one entry = 4 bars, tokens = active layers. Edit freely, every lane follows.
// K kick · C clap · H hats · O open hats · P perc · S shaker · B bass · b filtered bass · V bass variation
// Y hook · y filtered hook · W hook variation · X vox/alt hook · D pad · R riser/roll · M mini-break (last bar:
// no kick/bass, clap roll). A section's last bar with K = fill.
const PLAN = [
  ['intro', ['K', 'K H', 'K H P b', 'K C H P b']],
  ['groove', ['K C H P B', 'K C H P B', 'K C H P B Y', 'K C H P B Y M', 'K C H O P B Y W', 'K C H O P B Y W', 'K C H O P B Y W X', 'K C H O P B Y W X M', 'K C H O P B V Y X', 'K C H O P B V Y X']],
  ['brk', ['H b y X D', 'C H b Y X R']],
  ['grooveB', ['K C H S B V Y', 'K C H S B V Y', 'K C H P S B V Y', 'K C H P S B V Y', 'K C H P S B V Y W X', 'K C H P S B V Y W X']],
  ['break', ['y X D', 'y X D', 'H y X D', 'H b Y X D']],
  ['rise', ['H b Y D R', 'C H b Y D R']],
  ['drop', ['K C H O P S B Y X', 'K C H O P S B Y X', 'K C H P S B Y X', 'K C H P S B Y X', 'K C H P S B V Y W X', 'K C H P S B V Y W X', 'K C H P B V Y W X', 'K C H P B V Y W X']],
  ['groove2', ['K C H O P B V Y', 'K C H O P B V Y', 'K C H O P B V', 'K C H O P B V M', 'K C H P S B V', 'K C H P S B V']],
  ['outro', ['K C H P S', 'K C H P', 'K H P', 'K H']],
]
const bars = (f) => '<' + PLAN.flatMap(([n, c]) => Array.from({length: c.length * 4},
  (_, i) => f(n, i, c.length * 4, c[Math.floor(i / 4)].split(' ')))).join(' ') + '>'
const seq = (f) => mini(bars(f))
const on = (f) => seq((n, i, l, t) => f(n, i, l, t) ? 1 : 0)       // 1 bar = 1 cycle
const has = (t, ...k) => k.some((x) => t.includes(x))
const mb = (t, i) => t.includes('M') && i % 4 == 3                 // mini-break bar
const fill = (n, i, l, t) => i == l - 1 && has(t, 'K') && n != 'outro'
const tri = (x) => 1 - Math.abs(2 * x - 1)
const r2 = (x) => Math.round(x * 100) / 100

// ---- drums (bar variants: [main, phrase-end variation, section-end fill])
const KICK_POS = [1, 1, 1, 0, 1, 1, 0, 1]   // phrase positions (bar % 8) using the variation
const KICK = [
  "bd ~ ~ ~ bd ~ ~ ~ bd ~ ~ ~ bd ~ ~ ~",
  "bd ~ ~ ~ bd ~ ~ ~ bd ~ bd ~ bd ~ ~ ~",
  "bd ~ ~ ~ bd ~ ~ ~ bd ~ ~ ~ ~ ~ bd ~"
]
$: s(seq((n, i, l, t) => fill(n, i, l, t) ? 2 : KICK_POS[i % 8]).pick(KICK)).bank('RolandTR909').lpf(9000).hpf(45).gain(0.8)
  .mask(on((n, i, l, t) => has(t, 'K') && !mb(t, i)))
const KSUB = [
  "f#1 ~ ~ ~ f#1 ~ ~ ~ f#1 ~ ~ ~ f#1 ~ ~ ~",
  "f#1 ~ ~ ~ f#1 ~ ~ ~ f#1 ~ f#1 ~ f#1 ~ ~ ~",
  "f#1 ~ ~ ~ f#1 ~ ~ ~ f#1 ~ ~ ~ ~ ~ f#1 ~"
]
$: note(seq((n, i, l, t) => fill(n, i, l, t) ? 2 : KICK_POS[i % 8]).pick(KSUB)).s('sine').penv(24).pdecay(.045)   // sub-kick tuned to the key
  .attack(.001).decay(.3).sustain(0).release(.05).gain(0.9)
  .mask(on((n, i, l, t) => has(t, 'K') && !mb(t, i)))

const CLAP_POS = [0, 0, 0, 1, 0, 0, 0, 1]
const CLAP = [
  "~ ~ ~ ~ cp ~ ~ ~ ~ ~ ~ ~ cp ~ ~ ~",
  "~ ~ ~ ~ cp ~ ~ ~ ~ ~ ~ ~ cp ~ ~ cp"
]
$: s(seq((n, i) => CLAP_POS[i % 8]).pick(CLAP)).bank('RolandTR909').hpf(250).gain(0.62).pan(.52)
  .mask(on((n, i, l, t) => has(t, 'C') && !mb(t, i)))

const HAT = [
  "hh ~ hh ~ hh hh hh hh hh ~ hh ~ hh ~ hh ~",
  "hh ~ hh ~ hh hh hh hh hh ~ hh ~ hh hh hh hh"
]
$: s(seq((n, i) => i % 8 == 7 ? 1 : 0).pick(HAT)).bank('RolandTR909').hpf(7000)
  .gain("0.307 0.176 0.416 0.189 0.29 0.21 0.407 0.231 0.286 0.176 0.412 0.189 0.286 0.176 0.42 0.189")   // accents x level
  .velocity(ENERGY).postgain(seq((n, i, l, t) => has(t, 'K') ? 1 : .7)).pan("[.42 .58]*8")
  .mask(on((n, i, l, t) => has(t, 'H')))

// open hats on the off-beats (DNA: the reference's hats open up later)
$: s("~ ~ oh ~ ~ ~ oh ~ ~ ~ oh ~ ~ ~ oh ~").bank('RolandTR909').hpf(6000).cut(1).pan(.6)
  .velocity(ENERGY).gain(seq((n, i) => r2(0.26 * (.6 + .4 * (i % 16) / 15))))
  .mask(on((n, i, l, t) => has(t, 'O') && !mb(t, i)))

$: s("<[~ ~ ~ ~ ~ ~ ~ rim ~ ~ ~ ~ ~ rim ~ rim] [~ ~ ~ ~ ~ ~ ~ rim ~ rim ~ ~ ~ rim ~ ~]>").bank('RolandTR909').hpf(400)
  .gain(0.42).velocity(ENERGY).pan("<.3 .7>").delay(.22).delaytime(0.3629).delayfeedback(.3)
  .mask(on((n, i, l, t) => has(t, 'P')))

$: s("sh sh sh sh sh sh sh sh sh sh sh sh sh sh sh sh").bank('RolandTR808').hpf(5000).pan(.35)
  .gain("[0.11 0.055 0.22 0.066]*4").velocity(ENERGY)
  .mask(on((n, i, l, t) => has(t, 'S')))

// fills: clap roll on the last bar of a section and in mini-breaks, rolling build-up under R
const FILL = [
  "~",
  "~ ~ ~ ~ ~ ~ ~ ~ cp cp cp cp cp cp cp cp",
  "cp ~ cp ~ cp ~ cp ~ cp ~ cp ~ cp ~ cp ~",
  "cp cp cp cp cp cp cp cp cp cp cp cp cp cp cp cp"
]
$: s(seq((n, i, l, t) => has(t, 'R') ? ((i % 8) < 4 ? 2 : 3) : (fill(n, i, l, t) || mb(t, i)) ? 1 : 0).pick(FILL)).bank('RolandTR909')
  .gain(seq((n, i, l, t) => r2(0.55 * (has(t, 'R') ? .3 + .7 * (i % 8) / 7 : .8))))
  .hpf(seq((n, i, l, t) => has(t, 'R') ? Math.round(300 + 2500 * (i % 8) / 7) : 300))

// impact on the downbeat of every section / 16-bar phrase with a kick
$: s('cr').bank('RolandTR909').hpf(2500).gain(0.32)
  .mask(on((n, i, l, t) => i % 16 == 0 && has(t, 'K') && n != 'intro' && n != 'outro'))

// ---- bass: 2-bar loops (A, variation V), root f#2, 8.0 notes/bar,
