// open: slow 16-bar filter move around CUT; b (filtered): rises over each 8 bars
const bcut = seq((n, i, l, t) => has(t, 'B') ? Math.round(CUT * (.7 + .6 * tri((i % 16) / 16))) : Math.round(160 + 360 * (i % 8) / 7))
$: note(bsel.pick(BASS)).s('sine').velocity(bsel.pick(BASS_VEL)).postgain(PUMP)   // sub
